        vm.startPrank(user3);
        CDO.requestWithdraw(0,TranchTokenAA);
        CDO.claimWithdrawRequest();
        CDO.depositAA(IERC20(underlyingToken).balanceOf(address(user3)));
        CDO.requestWithdraw(0,TranchTokenAA);
        CDO.claimWithdrawRequest();
        CDO.depositAA(IERC20(underlyingToken).balanceOf(address(user3)));
        CDO.requestWithdraw(0,TranchTokenAA);
