As we can see, `executionData.tokenId` is passed to the `_processOffersFromExecutionData()` function instead of `loan.nftCollateralTokenId`. This function performs all the checks to ensure that the lenders’ offers accept this NFT.
```solidity
function _processOffersFromExecutionData(
    address _borrower,
    address _principalReceiver,
    address _principalAddress,
    address _nftCollateralAddress,
    uint256 _tokenId,
    uint256 _duration,
    OfferExecution[] calldata _offerExecution
) private returns (uint256, uint256[] memory, Loan memory, uint256) {
  ...
  _validateOfferExecution(
      thisOfferExecution,
      _tokenId,
      offer.lender,
      offer.lender,
      thisOfferExecution.lenderOfferSignature,
      protocolFee.fraction,
      totalAmount
  );
  ...
}
```
Eventually, it calls the `_checkValidators()` function to check the NFT token ID.
```solidity
function _checkValidators(LoanOffer calldata _loanOffer, uint256 _tokenId) private {
    uint256 offerTokenId = _loanOffer.nftCollateralTokenId;
    if (_loanOffer.nftCollateralTokenId != 0) {
        if (offerTokenId != _tokenId) {
            revert InvalidCollateralIdError();
        }
    } else {
        uint256 totalValidators = _loanOffer.validators.length;
        if (totalValidators == 0 && _tokenId != 0) {
            revert InvalidCollateralIdError();
        } else if ((totalValidators == 1) && (_loanOffer.validators[0].validator == address(0))) {
            return;
        }
        for (uint256 i = 0; i < totalValidators;) {
            IBaseLoan.OfferValidator memory thisValidator = _loanOffer.validators[i];
            IOfferValidator(thisValidator.validator).validateOffer(_loanOffer, _tokenId, thisValidator.arguments);
            unchecked {
                ++i;
            }
        }
    }
}
```
However, since `executionData.tokenId` is passed in, an attacker could pass in a valid `tokenId` (an NFT id that will be accepted by all lender offers). But in reality, the `loan.nftCollateralTokenId` will be the NFT kept in escrow.

description:
In `deployWithdrawalQueue()`, only clears `_queueOutstandingValues[lastQueueIndex]` and `_outstandingValues`, but doesn’t clear `_queueAccounting[lastQueueIndex]`.
```solidity
function deployWithdrawalQueue() external nonReentrant {
    ...

    /// @dev We move outstanding values from the pool to the queue that was just deployed.
    _queueOutstandingValues[pendingQueueIndex] = _outstandingValues;
    /// @dev We clear values of the new pending queue.
    delete _queueOutstandingValues[lastQueueIndex];
    delete _outstandingValues;
    //@audit miss delete _queueAccounting[lastQueueIndex]

    _updateLoanLastIds();

    _pendingQueueIndex = lastQueueIndex;

    // Cannot underflow because the sum of all withdrawals is never larger than totalSupply.
    unchecked {
        totalSupply -= sharesPendingWithdrawal;
    }
}
```
After this method, anyone calling `queueClaimAll()` will use this stale data `_queueAccounting[lastQueueIndex]`.

`queueClaimAll()` -> `_queueClaimAll(_pendingQueueIndex)`-> `_updatePendingWithdrawalWithQueue(_pendingQueueIndex)`
```solidity
function _updatePendingWithdrawalWithQueue(
    uint256 _idx,
    uint256 _cachedPendingQueueIndex,
    uint256[] memory _pendingWithdrawal
) private returns (uint256[] memory) {
    uint256 totalReceived = getTotalReceived[_idx];
    uint256 totalQueues = getMaxTotalWithdrawalQueues + 1;
    /// @dev Nothing to be returned
    if (totalReceived == 0) {
        return _pendingWithdrawal;
    }
    getTotalReceived[_idx] = 0;

    /// @dev We go from idx to newer queues. Each getTotalReceived is the total
    /// returned from loans for that queue. All future queues/pool also have a piece of it.
    /// X_i: Total received for queue `i`
    /// X_1  = Received * shares_1 / totalShares_1
    /// X_2 = (Received - (X_1)) * shares_2 / totalShares_2 ...
    /// Remainder goes to the pool.
    for (uint256 i; i < totalQueues;) {
        uint256 secondIdx = (_idx + i) % totalQueues;
        QueueAccounting memory queueAccounting = _queueAccounting[secondIdx];
        if (queueAccounting.thisQueueFraction == 0) {
            unchecked {
                ++i;
            }
            continue;
        }
        /// @dev We looped around.
        if (secondIdx == _cachedPendingQueueIndex + 1) {
            break;
        }
        uint256 pendingForQueue = totalReceived.mulDivDown(queueAccounting.thisQueueFraction, PRINCIPAL_PRECISION);
        totalReceived -= pendingForQueue;

        _pendingWithdrawal[secondIdx] = pendingForQueue;
        unchecked {
            ++i;
        }
    }
    return _pendingWithdrawal;
}
```

There are tokens that have token/ETH but no token/USD Chainlink oracles currently in which these tokens have the in scope token behaviors described in <https://code4rena.com/audits/2024-04-noya> and should be supported by this protocol. To support these tokens, the ETH/USD Chainlink oracle can be used as a part of the route set by the following `NoyaValueOracle.updatePriceRoute` function for converting the token amount to ETH first and then converting the converted ETH amount to USD.

```solidity
function updatePriceRoute(address asset, address base, address[] calldata s) external onlyMaintainer {
    priceRoutes[asset][base] = s;
    emit UpdatedPriceRoute(asset, base, s);
}
```

When converting the value of such token in ETH to USD, the following `ChainlinkOracleConnector.getValue` function would return `getValueFromChainlinkFeed(AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse)`; because `amountIn` is in ETH’s decimals that is 18 and `uintprice` and `sourceTokenUnit` are in USD’s decimals that is 8 in the `getValueFromChainlinkFeed` function below, the value returned by the `ChainlinkOracleConnector.getValue` function is in ETH’s decimals. Hence, when converting such token amount to ETH first and then to USD, the value of the corresponding token amount is in ETH’s decimals instead of USD’s decimals. In comparison, if the token/USD oracle could exist and be used for such token, the value of such token returned by `ChainlinkOracleConnector.getValue` function would be in USD’s decimals instead of ETH’s decimals. Thus, the value of such token is much higher when using the token/ETH and ETH/USD oracles indirectly comparing to using the token/USD oracle directly given if such token/USD oracle can become existent in the future. If such token/USD oracle does become existent and be used in the `ChainlinkOracleConnector` contract in the future, the value of such token amount calculated previously using the token/ETH and ETH/USD oracles indirectly would be incorrectly much higher than the value of the same token amount newly calculated using the token/USD oracle directly.

```solidity
function getValue(address asset, address baseToken, uint256 amount) public view returns (uint256) {
    if (asset == baseToken) {
        return amount;
    }

    (address primarySource, bool isPrimaryInverse) = getSourceOfAsset(asset, baseToken);
    if (primarySource == address(0)) {
        revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(asset, baseToken, primarySource);
    }
    address decimalsSource = isPrimaryInverse ? baseToken : asset;
    decimalsSource = decimalsSource == ETH || decimalsSource == USD ? primarySource : decimalsSource;
    return getValueFromChainlinkFeed(
        AggregatorV3Interface(primarySource), amount, getTokenDecimals(decimalsSource), isPrimaryInverse
    );
}

function getTokenDecimals(address token) public view returns (uint256) {
    uint256 decimals = IERC20Metadata(token).decimals();
    return 10 ** decimals;
}

function getValueFromChainlinkFeed(
    AggregatorV3Interface source,
    uint256 amountIn,
    uint256 sourceTokenUnit,
    bool isInverse
) public view returns (uint256) {
    int256 price;
    uint256 updatedAt;
    (, price,, updatedAt,) = source.latestRoundData();
    uint256 uintprice = uint256(price);
    if (block.timestamp - updatedAt > chainlinkPriceAgeThreshold) {
        revert NoyaChainlinkOracle_DATA_OUT_OF_DATE();
    }
    if (price <= 0) {
        revert NoyaChainlinkOracle_PRICE_ORACLE_UNAVAILABLE(address(source), address(0), address(0));
    }
    if (isInverse) {
        return (amountIn * sourceTokenUnit) / uintprice;
    }
    return (amountIn * uintprice) / (sourceTokenUnit);
}
```

