    // @audit-info bob owed 120e6 debt
    assertEq(size.getUserView(bob).debtBalance, 120e6);
    // @audit-info feeRecipient received 497500 szaUSDC as fee
    assertEq(size.getUserView(feeRecipient).borrowATokenBalance, 497500);
}
