            uint256 indexed txid,
            address indexed from,
            uint256 indexed to,
            string from_chain,
            string to_chain,
            address from_token,
            uint256 to_token,
            uint256 amount,
            SettlementMode mode
        );
```

However, the method, once more sends the incorrect `from_token` address:
```solidity
